logic:
// frmAccionistasContacto — Accionistas de un contacto tipo Empresa. AXX-248 / GLOB-1216.
// Solo la relacion {id, porcentaje} es dato propio de esta pestania: numero SIS, nombre,
// COBIS (nationalId) y PEP (publicStatus) se resuelven contra el contacto en cada dibujado.
var mi = this;

var ACC_TAB = 'Accionistas';
var ACC_VAR = 'customContactForm_' + ACC_TAB;
var ACC_CAMPO = 'Accionistas';
var ACC_PAGINA = 20;      // AXX-248 asuncion 1
var ACC_DEBOUNCE = 300;   // AXX-248 asuncion 2
var ACC_MIN = 3;          // CA8

var accLista = [];        // [{id, porcentaje}] — sigue al usuario entre redibujados
var accCache = {};        // id -> contacto resuelto en vivo
var accCargado = false;
var accSecuencia = 0;     // cancela la peticion en vuelo del autocomplete

function accEsc(s) { return String(s === null || s === undefined ? '' : s).replace(/'/g, "''"); }

function accHtml(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function accContenedor() {
  var i = window[ACC_VAR];
  return (i && i.instanceContainers && i.instanceContainers[0]) ? i.instanceContainers[0] : null;
}

function accCampo() {
  var c = accContenedor();
  var $c = c ? $(c).find('[name="' + ACC_CAMPO + '"]') : $();
  if (!$c.length) $c = $('#' + ACC_CAMPO);
  return $c;
}

function accContactoId() {
  try {
    var v = (typeof contactForm !== 'undefined' && contactForm) ? contactForm.getFieldsValue() : null;
    if (v && v.id) return String(v.id);
  } catch (e) { /* sigue por la URL */ }
  var m = String((window.location && window.location.pathname) || '').match(/\/contact\/(\d+)/);
  return m ? m[1] : null;
}

// Empresa = isPerson falso. La pestania solo aplica a contactos tipo Empresa.
function accEsEmpresa() {
  try {
    var v = (typeof contactForm !== 'undefined' && contactForm) ? contactForm.getFieldsValue() : null;
    if (v && typeof v.isPerson !== 'undefined' && v.isPerson !== null) return !v.isPerson;
  } catch (e) { /* sin dato en pantalla */ }
  var id = accContactoId();
  if (!id) return true;                       // alta nueva: no la escondemos a ciegas
  var c = accCache['self:' + id];
  return c ? !c.isPerson : true;
}

// ---------------------------------------------------------------- persistencia
function accLeerHidden() {
  var $c = accCampo();
  var raw = $c.length ? String($c.val() || '').trim() : '';
  if (!raw) return [];
  try {
    var arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

function accPersistir() {
  var $c = accCampo();
  if ($c.length) $c.val(JSON.stringify(accLista));
}

// ------------------------------------------------------------------ validacion
// A6: decimal hasta 2 decimales, > 0 y <= 100. Nulo, cero, negativo y no numerico
// se rechazan con el mismo tratamiento que > 100.
function accValidarPorcentaje(valor) {
  var s = String(valor === null || valor === undefined ? '' : valor).trim().replace(',', '.');
  if (s === '') return { ok: false, msg: 'Indique el porcentaje de participación.' };
  if (!/^\d+(\.\d{1,2})?$/.test(s)) {
    return { ok: false, msg: 'El porcentaje debe ser un número decimal con hasta 2 decimales, mayor que 0 y menor o igual a 100.' };
  }
  var n = parseFloat(s);
  if (!isFinite(n) || n <= 0) return { ok: false, msg: 'El porcentaje debe ser mayor que 0.' };
  if (n > 100) return { ok: false, msg: 'El porcentaje de participación no puede ser mayor a 100.' };
  return { ok: true, valor: Math.round(n * 100) / 100 };
}

function accAcumulado(excluirId) {
  var t = 0;
  accLista.forEach(function (a) {
    if (excluirId !== undefined && excluirId !== null && String(a.id) === String(excluirId)) return;
    t += parseFloat(a.porcentaje) || 0;
  });
  return Math.round(t * 100) / 100;
}

// --------------------------------------------------------------- datos en vivo
function accComponerNombre(c) {
  if (!c) return '';
  if (c.isPerson) return [c.name, c.surname1].filter(function (x) { return String(x || '').trim(); }).join(' ').trim();
  return String(c.surname2 || c.name || '').trim();
}

// CA10 / CA14: se releen los contactos en cada dibujado, nunca se copian al hidden.
async function accResolverContactos(ids) {
  var faltan = ids.filter(function (i) { return !accCache[i]; });
  if (!faltan.length) return;
  try {
    var r = await mi.exe('GetContacts', {
      size: faltan.length, page: 0,
      filter: 'id IN (' + faltan.map(function (i) { return parseInt(i, 10) || 0; }).join(',') + ')'
    });
    if (r && r.ok) (r.outData || []).forEach(function (c) { accCache[String(c.id)] = c; });
  } catch (e) { console.error('Accionistas: no se pudieron resolver los contactos', e); }
}

// ------------------------------------------------------------------- busqueda
// CA3 persona por nombre, CA4 empresa por nombre, CA5 cnp/nif, CA6 Id.
function accFiltro(termino) {
  var t = String(termino || '').trim();
  var q = accEsc(t);
  var partes = [];
  if (/^\d+$/.test(t)) partes.push('id = ' + parseInt(t, 10));           // CA6/CA8: Id no exige 3 caracteres
  if (t.length >= ACC_MIN) {
    partes.push("(isPerson = 1 AND (name LIKE '" + q + "%' OR surname1 LIKE '" + q + "%' OR cnp LIKE '" + q + "%'))");
    partes.push("(isPerson = 0 AND (surname2 LIKE '" + q + "%' OR nif LIKE '" + q + "%'))");
  }
  return partes.length ? partes.join(' OR ') : null;
}

async function accBuscar(termino, pagina) {
  var filtro = accFiltro(termino);
  if (!filtro) return { items: [], total: 0, corto: true };
  var r = await mi.exe('GetContacts', { size: ACC_PAGINA, page: pagina, filter: filtro });
  if (!r || !r.ok) throw new Error((r && r.msg) || 'No se pudo consultar contactos');
  var items = (r.outData || []).map(function (c) {
    accCache[String(c.id)] = c;
    return { id: c.id, etiqueta: '[' + c.id + '] ' + accComponerNombre(c) + (c.isPerson ? (c.cnp ? ' — ' + c.cnp : '') : (c.nif ? ' — ' + c.nif : '')) };
  });
  return { items: items, total: r.total || 0, corto: false };
}

// -------------------------------------------------------------------- interfaz
function accMensaje(msg, tipo) {
  try { mi.message[tipo === 'error' ? 'error' : (tipo === 'warning' ? 'warning' : 'success')](msg); return; } catch (e) { /* toast propio */ }
}

function accPintar() {
  var cont = accContenedor();
  if (!cont) return;
  var $form = $(cont);
  var $panel = $form.find('#accPanel');
  if (!$panel.length) return;

  var ids = accLista.map(function (a) { return String(a.id); });
  accResolverContactos(ids).then(function () {
    var filas = accLista.map(function (a) {
      var c = accCache[String(a.id)] || null;
      var pep = c ? (c.publicStatus ? 'Sí' : 'No') : '—';
      var cobis = c ? accHtml(c.nationalId || '') : '—';
      return '<tr>' +
        '<td>' + accHtml(a.id) + '</td>' +
        '<td>' + accHtml(c ? accComponerNombre(c) : '(contacto no disponible)') + '</td>' +
        '<td style="text-align:right">' + accHtml(a.porcentaje) + '</td>' +
        '<td>' + cobis + '</td>' +
        '<td>' + pep + '</td>' +
        '<td><a class="accEditar" data-id="' + accHtml(a.id) + '">Editar</a> · ' +
        '<a class="accQuitar" data-id="' + accHtml(a.id) + '">Quitar</a></td>' +
        '</tr>';
    }).join('');

    var total = accAcumulado();
    $panel.find('#accCuerpo').html(filas || '<tr><td colspan="6" style="text-align:center;color:#999">Sin accionistas registrados</td></tr>');
    $panel.find('#accTotal').text(total);
    $panel.find('#accDisponible').text(Math.round((100 - total) * 100) / 100);
  });
}

function accConstruir() {
  var cont = accContenedor();
  if (!cont) return false;
  var $form = $(cont);
  if ($form.find('#accPanel').length) return true;   // idempotente

  var $panel = $('<div id="accPanel" style="margin-top:10px"></div>');
  $panel.html(
    '<div class="ant-card ant-card-bordered"><div class="ant-card-body">' +
    '<div style="margin-bottom:8px">' +
    '<button type="button" id="accBtnAgregar" class="ant-btn ant-btn-primary">+ Agregar accionista</button>' +
    '<span style="margin-left:16px">Participación registrada: <b id="accTotal">0</b>% · disponible: <b id="accDisponible">100</b>%</span>' +
    '</div>' +
    '<table class="ant-table" style="width:100%">' +
    '<thead class="ant-table-thead"><tr>' +
    '<th>Número (SIS)</th><th>Nombre completo</th><th style="text-align:right">% Participación</th>' +
    '<th>COBIS</th><th>PEP</th><th>Acciones</th>' +
    '</tr></thead><tbody id="accCuerpo"></tbody></table>' +
    '</div></div>'
  );
  $form.append($panel);
  return true;
}

function accModal(edicionId) {
  $('#accModal, #accMask').remove();
  var editando = edicionId !== undefined && edicionId !== null;
  var actual = editando ? accLista.filter(function (a) { return String(a.id) === String(edicionId); })[0] : null;

  var $mask = $('<div id="accMask"></div>').css({
    position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
    background: 'rgba(0,0,0,.45)', 'z-index': 10000
  });
  var $modal = $('<div id="accModal"></div>').css({
    position: 'fixed', top: '15%', left: '50%', transform: 'translateX(-50%)',
    width: '520px', background: '#fff', padding: '16px', 'border-radius': '4px',
    'z-index': 10001, 'box-shadow': '0 4px 12px rgba(0,0,0,.15)'
  }).html(
    '<h3>' + (editando ? 'Editar accionista' : 'Agregar accionista') + '</h3>' +
    '<div style="margin-bottom:8px"><label>Accionista (nombre, identificación o Id)</label>' +
    '<input type="text" id="accInput" class="ant-input" autocomplete="off" ' +
    (editando ? 'disabled ' : '') + '/>' +
    '<div id="accEstado" style="font-size:12px;color:#999;min-height:18px"></div></div>' +
    '<div style="margin-bottom:8px"><label>% de participación</label>' +
    '<input type="text" id="accPorcentaje" class="ant-input" /></div>' +
    '<div id="accError" style="color:#ff4d4f;min-height:20px"></div>' +
    '<div style="text-align:right;margin-top:8px">' +
    '<button type="button" id="accCancelar" class="ant-btn">Cancelar</button> ' +
    '<button type="button" id="accGuardar" class="ant-btn ant-btn-primary">Guardar</button></div>'
  );
  $('body').append($mask).append($modal);

  var elegido = editando ? String(edicionId) : null;
  if (editando) {
    var c = accCache[String(edicionId)];
    $modal.find('#accInput').val('[' + edicionId + '] ' + accComponerNombre(c));
    $modal.find('#accPorcentaje').val(actual ? actual.porcentaje : '');
  }

  function cerrar() { $('#accModal, #accMask').remove(); }
  $mask.on('click', cerrar);
  $modal.find('#accCancelar').on('click', cerrar);

  // ---- autocomplete: 20 por pagina + paginacion, debounce 300 ms con cancelacion
  var $input = $modal.find('#accInput');
  var $estado = $modal.find('#accEstado');
  var $dd = null, pagina = 0, total = 0, termino = '', temporizador = null;

  function quitarDd() { if ($dd) { $dd.remove(); $dd = null; } }

  function pintarDd(items) {
    quitarDd();
    $dd = $('<div></div>').css({
      position: 'absolute', background: '#fff', border: '1px solid #d9d9d9',
      width: $input.outerWidth(), 'max-height': '220px', overflow: 'auto', 'z-index': 10002,
      'box-shadow': '0 2px 8px rgba(0,0,0,.15)'
    }).css({ top: $input.position().top + $input.outerHeight(), left: $input.position().left });

    items.forEach(function (it) {
      $('<div class="accOpcion"></div>').attr('data-id', it.id)
        .text(it.etiqueta).css({ padding: '4px 8px', cursor: 'pointer' })
        .on('mouseenter', function () { $(this).css('background', '#bae7ff'); })
        .on('mouseleave', function () { $(this).css('background', '#fff'); })
        .on('click', function () { elegido = String(it.id); $input.val(it.etiqueta); quitarDd(); $estado.text(''); })
        .appendTo($dd);
    });

    var paginas = Math.ceil(total / ACC_PAGINA);
    if (paginas > 1) {
      var $pg = $('<div></div>').css({ display: 'flex', 'justify-content': 'space-between', padding: '4px 8px', 'border-top': '1px solid #d9d9d9' });
      var $prev = $('<button type="button">«</button>').prop('disabled', pagina === 0);
      var $info = $('<span></span>').text((pagina + 1) + ' / ' + paginas + ' (' + total + ')');
      var $next = $('<button type="button">»</button>').prop('disabled', pagina >= paginas - 1);
      $prev.on('click', function () { if (pagina > 0) { pagina--; consultar(termino, pagina); } });
      $next.on('click', function () { if (pagina < paginas - 1) { pagina++; consultar(termino, pagina); } });
      $pg.append($prev, $info, $next);
      $dd.append($pg);
    }
    $modal.append($dd);
  }

  async function consultar(t, p) {
    var propia = ++accSecuencia;              // cancelacion de la peticion en vuelo
    $estado.text('Buscando...');
    try {
      var r = await accBuscar(t, p);
      if (propia !== accSecuencia) return;    // llego tarde: se descarta
      if (r.corto) { quitarDd(); $estado.text('Escriba al menos ' + ACC_MIN + ' caracteres, o un Id numérico.'); return; }
      total = r.total;
      if (!r.items.length) { quitarDd(); $estado.text('Sin resultados para "' + t + '".'); return; }
      $estado.text(total + ' resultado(s).');
      pintarDd(r.items);
    } catch (e) {
      if (propia !== accSecuencia) return;
      quitarDd();
      $estado.text('Error al consultar contactos. Reintente.');
    }
  }

  $input.on('input', function () {
    elegido = null;
    var t = String($(this).val() || '').trim();
    termino = t; pagina = 0;
    if (temporizador) clearTimeout(temporizador);
    accSecuencia++;                            // invalida lo que este en vuelo
    if (!t) { quitarDd(); $estado.text(''); return; }
    if (!/^\d+$/.test(t) && t.length < ACC_MIN) { quitarDd(); $estado.text('Escriba al menos ' + ACC_MIN + ' caracteres, o un Id numérico.'); return; }
    temporizador = setTimeout(function () { consultar(termino, 0); }, ACC_DEBOUNCE);
  });

  // ---- guardar
  $modal.find('#accGuardar').on('click', function () {
    var $err = $modal.find('#accError');
    $err.text('');
    if (!elegido) { $err.text('Seleccione un accionista de la lista. Debe existir previamente como contacto.'); return; }

    var v = accValidarPorcentaje($modal.find('#accPorcentaje').val());
    if (!v.ok) { $err.text(v.msg); return; }

    // CA13 / A13: duplicidad por (empresa, contacto) segun el Id del contacto.
    if (!editando && accLista.some(function (a) { return String(a.id) === String(elegido); })) {
      $err.text('Ese contacto ya está registrado como accionista de esta empresa.');
      return;
    }
    // CA12 / A5: acumulado <= 100. No se exige que sume exactamente 100.
    var acumulado = accAcumulado(editando ? edicionId : null) + v.valor;
    if (Math.round(acumulado * 100) / 100 > 100) {
      $err.text('La suma de participaciones no puede superar 100. Registrado: ' +
        accAcumulado(editando ? edicionId : null) + '%, disponible: ' +
        (Math.round((100 - accAcumulado(editando ? edicionId : null)) * 100) / 100) + '%.');
      return;
    }

    if (editando) {
      accLista.forEach(function (a) { if (String(a.id) === String(edicionId)) a.porcentaje = v.valor; });
    } else {
      accLista.push({ id: parseInt(elegido, 10), porcentaje: v.valor });
    }
    accPersistir();
    accPintar();
    cerrar();
    accMensaje(editando ? 'Accionista actualizado.' : 'Accionista agregado.', 'success');
  });
}

// ------------------------------------------------------------------- cableado
function accEventos() {
  var cont = accContenedor();
  if (!cont) return;
  var $form = $(cont);
  $form.off('click.acc').on('click.acc', '#accBtnAgregar', function () { accModal(null); })
    .on('click.acc', '.accEditar', function () { accModal($(this).data('id')); })
    .on('click.acc', '.accQuitar', function () {
      var id = String($(this).data('id'));
      accLista = accLista.filter(function (a) { return String(a.id) !== id; });
      accPersistir(); accPintar();
    });
}

// Solo contactos tipo Empresa: la pestania se oculta en personas.
// `condition` en $.Contacts.customForms NO la lee el producto (AXX-248 D3).
function accVisibilidad() {
  var $tab = $('[data-node-key="customTab_' + ACC_TAB + '"]');
  if (!$tab.length) return;
  if (accEsEmpresa()) $tab.show(); else $tab.hide();
}

// La pestania se dibuja DOS veces y gana la instantanea guardada: el panel se
// re-asegura tras cada dibujado, de forma idempotente y sin volver a pedir datos.
function accAsegurar() {
  try {
    accVisibilidad();
    if (!accEsEmpresa()) return;
    var cont = accContenedor();
    if (!cont) return;
    if (!accCargado) {
      var guardado = accLeerHidden();
      if (guardado.length) { accLista = guardado; accCargado = true; }
    }
    var nuevo = !$(cont).find('#accPanel').length;
    if (accConstruir() && nuevo) { accEventos(); accPintar(); }
    accPersistir();   // el hidden lo repone el segundo dibujado: se vuelve a escribir
  } catch (e) { console.error('Accionistas:', e); }
}

// El contacto propio, para saber si es Empresa cuando la pantalla aun no lo expone.
(async function accPrecargar() {
  var id = accContactoId();
  if (!id) return;
  try {
    var r = await mi.exe('GetContacts', { filter: 'id = ' + parseInt(id, 10), size: 1 });
    if (r && r.ok && r.outData && r.outData[0]) accCache['self:' + id] = r.outData[0];
  } catch (e) { /* la pantalla decide */ }
})();

if (window.__accTimer) clearInterval(window.__accTimer);
var accTicks = 0;
window.__accTimer = setInterval(function () {
  if (++accTicks > 2400) { clearInterval(window.__accTimer); window.__accTimer = null; return; }
  accAsegurar();
}, 500);

accAsegurar();
